def ichol(A):
    """Inputs:
    A : Matrix, 2d array M * M
    Outputs:
    A : Matrix, 2d array M * M (modified in-place with incomplete Cholesky factorization)
    """
    M = A.shape[0]
    L = A.copy()
    for i in range(M):
        sum_diag = 0.0
        for k in range(i):
            if L[i, k] != 0:
                sum_diag += L[i, k] ** 2
        diag_value = L[i, i] - sum_diag
        if diag_value <= 0:
            diag_value = 0.0
        L[i, i] = np.sqrt(diag_value)
        for j in range(i + 1, M):
            if L[j, i] != 0:
                sum_off_diag = 0.0
                for k in range(i):
                    if L[i, k] != 0 and L[j, k] != 0:
                        sum_off_diag += L[i, k] * L[j, k]
                if L[i, i] != 0:
                    L[j, i] = (L[j, i] - sum_off_diag) / L[i, i]
                else:
                    L[j, i] = 0.0
            else:
                L[j, i] = 0.0
        for j in range(i):
            L[j, i] = 0.0
    return L
